  --sidebar-width: 270px;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

[data-theme="dark"] {
  --bg-page: #0a1124;
  --bg-sidebar: #0f1933;
  --bg-card: #132042;
  --bg-subtle: #172449;
  --bg-hover: #1a2952;

