  color: #fff;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-full);
}

.bookmark-verse-quote {
  font-size: 1.05rem;
  font-style: italic;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 16px;
}

.bookmark-card-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.btn-bookmark-action {
  font-size: 0.84rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.btn-bm-read {
  background: var(--accent-blue-light);
  color: var(--accent-blue);
}

.btn-bm-copy {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
}

.btn-bm-delete {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  color: #dc2626;
  margin-left: auto;
}

/* Offline Storage Panel */
.offline-panel-header {
  margin-bottom: 28px;
}

.offline-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-navy);
}

.offline-subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-top: 4px;
  max-width: 780px;
}

.offline-cards-container {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.offline-status-box {
  padding: 20px 24px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  background: var(--bg-page);
}

.offline-box-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.offline-item-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-navy);
}

.offline-status-text {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.btn-offline-download {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  color: var(--text-navy);
  font-size: 0.84rem;
  font-weight: 600;
