  background: var(--bg-page);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.notice-icon {
  font-size: 1.1rem;
}

/* ==========================================================================
