/* ==========================================================================
   Grace Fellowship Church - Home Page Design System
   Matches Exact Screenshot UI Reference
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@600;700;800&family=Lora:ital,wght@0,400;0,500;0,600;1,400&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

:root {
  /* Primary Brand Palette */
  --navy-900: #0a1526;
  --navy-800: #0f1e36;
  --navy-700: #172a4c;
  --navy-600: #1e3a68;

  --blue-primary: #0066cc;
  --blue-hover: #0052a3;
  --blue-light: #e8f1fc;
  --blue-border: rgba(0, 102, 204, 0.2);

  --gold-accent: #c59b27;
  --gold-hover: #b0871d;
  --gold-light: #fff8e6;

  /* Neutrals */
  --bg-white: #ffffff;
  --bg-page: #fdfdfd;
  --bg-gray-50: #f8fafc;
  --bg-gray-100: #f1f5f9;
  --border-light: #e2e8f0;
  --border-subtle: #f1f5f9;

  /* Typography Colors */
  --text-navy: #0f1e36;
  --text-slate: #334155;
  --text-muted: #64748b;
  --text-light: #94a3b8;

  /* Shadows */
  --shadow-xs: 0 1px 2px rgba(15, 30, 54, 0.04);
  --shadow-sm: 0 2px 8px rgba(15, 30, 54, 0.06);
  --shadow-md: 0 4px 16px rgba(15, 30, 54, 0.08);
  --shadow-lg: 0 10px 30px rgba(15, 30, 54, 0.12);

  /* Radius */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 9999px;
}

/* Base Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background-color: var(--bg-white);
  color: var(--text-navy);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
  transition: all 0.2s ease;
}

button {
  font-family: inherit;
  border: none;
  outline: none;
  background: none;
  cursor: pointer;
  transition: all 0.2s ease;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Layout Utilities */
.home-container {
  max-width: 1220px;
  margin: 0 auto;
  padding: 0 24px;
}

.home-section {
  padding: 40px 0;
}

.section-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

.section-title-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.section-title-icon {
  font-size: 1.35rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.section-title-text {
  font-size: 1.45rem;
  font-weight: 700;
  color: var(--navy-800);
  letter-spacing: -0.01em;
}

.section-view-all {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: color 0.2s ease;
}

.section-view-all:hover {
  color: var(--blue-primary);
}

/* ==========================================================================
   1. Floating Navigation Bar
   ========================================================================== */
.church-navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--bg-white);
  box-shadow: 0 1px 4px rgba(15, 30, 54, 0.06);
  border-bottom: 1px solid rgba(15, 30, 54, 0.06);
  transition: all 0.25s ease;
}

.church-navbar.scrolled {
  box-shadow: 0 4px 20px rgba(15, 30, 54, 0.08);
}

.navbar-inner {
  max-width: 1260px;
  margin: 0 auto;
  padding: 12px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

/* Brand */
.nav-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}

.nav-brand-logo {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-cross-icon {
  font-size: 1.9rem;
  color: var(--gold-accent);
  line-height: 1;
}

.nav-brand-text {
  display: flex;
  flex-direction: column;
}

.nav-church-name {
  font-size: 1.12rem;
  font-weight: 800;
  color: var(--navy-800);
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.nav-church-tagline {
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: 0.02em;
  white-space: nowrap;
}

/* Nav Links */
.nav-links-desktop {
  display: flex;
  align-items: center;
  gap: 6px;
  list-style: none;
}

.nav-link-item {
  display: inline-block;
}

.nav-link-btn {
  padding: 8px 16px;
  border-radius: var(--radius-pill);
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-slate);
  text-decoration: none;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.nav-link-btn:hover {
  color: var(--blue-primary);
  background-color: var(--bg-gray-50);
}

.nav-link-btn.active {
  background-color: var(--blue-primary);
  color: #ffffff;
  font-weight: 600;
}

.nav-search-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-slate);
  font-size: 1.05rem;
  transition: background 0.2s;
  margin-left: 4px;
}

.nav-search-btn:hover {
  background-color: var(--bg-gray-100);
  color: var(--blue-primary);
}

.btn-nav-donate {
  padding: 8px 22px;
  border-radius: var(--radius-pill);
  background-color: var(--blue-primary);
  color: #ffffff;
  font-size: 0.92rem;
  font-weight: 600;
  text-decoration: none;
  transition: background 0.2s ease, transform 0.15s ease, box-shadow 0.2s ease;
  box-shadow: 0 2px 8px rgba(0, 102, 204, 0.25);
  white-space: nowrap;
}

.btn-nav-donate:hover {
  background-color: var(--blue-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(0, 102, 204, 0.35);
}

/* Hamburger for Mobile */
.hamburger-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 38px;
  height: 38px;
  border-radius: 8px;
  background: var(--bg-gray-100);
  gap: 5px;
}

.hamburger-bar {
  width: 20px;
  height: 2px;
  background-color: var(--navy-800);
  border-radius: 2px;
  transition: all 0.2s ease;
}

/* Mobile Drawer */
.mobile-nav-drawer {
  display: none;
  background: var(--bg-white);
  border-top: 1px solid var(--border-light);
  padding: 16px 24px 24px 24px;
  box-shadow: 0 10px 20px rgba(0,0,0,0.06);
}

.mobile-nav-drawer.open {
  display: block;
}

.mobile-nav-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.mobile-nav-list a {
  display: block;
  padding: 10px 14px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-navy);
  border-radius: var(--radius-sm);
}

.mobile-nav-list a.active {
  background: var(--blue-primary);
  color: #ffffff;
}

.mobile-nav-list a:hover:not(.active) {
  background: var(--bg-gray-100);
}

/* ==========================================================================
   2. Hero Section
   ========================================================================== */
.hero-section {
  position: relative;
  min-height: 480px;
  background-size: cover;
  background-position: center center;
  display: flex;
  align-items: center;
  color: #ffffff;
  padding: 70px 0;
  overflow: hidden;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(15, 30, 54, 0.35) 0%,
    rgba(15, 30, 54, 0.6) 60%,
    rgba(15, 30, 54, 0.75) 100%
  );
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 780px;
}

.hero-welcome {
  font-size: 1.6rem;
  font-weight: 500;
  color: #ffffff;
  margin-bottom: 4px;
  text-shadow: 0 2px 4px rgba(0,0,0,0.3);
}

.hero-title {
  font-size: 3.2rem;
  font-weight: 800;
  line-height: 1.15;
  color: #ffffff;
  margin-bottom: 16px;
  text-shadow: 0 2px 8px rgba(0,0,0,0.4);
  letter-spacing: -0.02em;
}

.hero-subtitle {
  font-size: 1.22rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.95);
  margin-bottom: 18px;
  line-height: 1.5;
  text-shadow: 0 1px 3px rgba(0,0,0,0.3);
}

.hero-verse {
  font-family: 'Lora', Georgia, serif;
  font-style: italic;
  font-size: 1rem;
  color: rgba(255, 255, 255, 0.88);
  margin-bottom: 28px;
  line-height: 1.6;
  max-width: 640px;
}

.hero-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-hero-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 28px;
  border-radius: var(--radius-pill);
  background-color: var(--blue-primary);
  color: #ffffff;
  font-size: 0.98rem;
  font-weight: 600;
  box-shadow: 0 4px 14px rgba(0, 102, 204, 0.4);
  transition: all 0.2s ease;
}

.btn-hero-primary:hover {
  background-color: var(--blue-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(0, 102, 204, 0.5);
}

.btn-hero-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  justify-content: center;
  padding: 11px 26px;
  border-radius: var(--radius-pill);
  background: rgba(15, 30, 54, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.65);
  color: #ffffff;
  font-size: 0.98rem;
  font-weight: 600;
  backdrop-filter: blur(4px);
  transition: all 0.2s ease;
}

.btn-hero-secondary:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: #ffffff;
  transform: translateY(-2px);
}

/* ==========================================================================
   3. Announcements Section
   ========================================================================== */
.announcements-box {
  background-color: #fdf5f5;
