/* ==========================================================================
   Navbar Component - Grace Fellowship Church
   Fixed floating navigation bar with mobile responsive drawer
   ========================================================================== */

function Navbar({ activeSection = "home", onNavigate }) {
  const [isScrolled, setIsScrolled] = React.useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);

  React.useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 20) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const navItems = [
    { id: "home", label: "Home", href: "#home" },
    { id: "about", label: "About", href: "#about" },
    { id: "bible", label: "Bible", href: "bible/index.html" },
    { id: "sermons", label: "Sermons", href: "#sermons" },
    { id: "events", label: "Events", href: "#events" },
    { id: "ministries", label: "Ministries", href: "#ministries" },
    { id: "gallery", label: "Gallery", href: "#gallery" },
    { id: "contact", label: "Contact", href: "#contact" }
  ];

  const handleLinkClick = (id, href, e) => {
    if (href.startsWith("#")) {
      e.preventDefault();
      setMobileMenuOpen(false);
      if (onNavigate) onNavigate(id);
      const target = document.getElementById(href.substring(1));
      if (target) {
        target.scrollIntoView({ behavior: "smooth" });
      }
    }
  };

  return (
    <header className={`church-navbar ${isScrolled ? "scrolled" : ""}`}>
      <div className="navbar-inner">
        {/* Brand */}
        <a href="#home" className="nav-brand" onClick={(e) => handleLinkClick("home", "#home", e)}>
          <div className="nav-brand-logo">
            <span className="nav-cross-icon">✝</span>
          </div>
          <div className="nav-brand-text">
            <span className="nav-church-name">Grace Fellowship Church</span>
            <span className="nav-church-tagline">Worship • Grow • Serve • Share</span>
          </div>
        </a>

        {/* Desktop Navigation */}
        <nav className="nav-links-desktop" aria-label="Main Navigation">
          {navItems.map((item) => (
            <li key={item.id} className="nav-link-item">
              <a
                href={item.href}
                className={`nav-link-btn ${activeSection === item.id ? "active" : ""}`}
                onClick={(e) => handleLinkClick(item.id, item.href, e)}
              >
                {item.label}
              </a>
            </li>
          ))}

          {/* Search Icon */}
          <button
            type="button"
            className="nav-search-btn"
            title="Search Scripture or Sermons"
            aria-label="Search"
            onClick={() => {
              window.location.href = "bible/index.html";
            }}
          >
            🔍
          </button>

          {/* Donate Button */}
          <a
            href="#donate"
            className="btn-nav-donate"
            onClick={(e) => handleLinkClick("donate", "#donate", e)}
          >
            Donate
          </a>
        </nav>

        {/* Mobile Hamburger Toggle */}
        <button
          type="button"
          className="hamburger-toggle"
          aria-label="Toggle navigation menu"
          aria-expanded={mobileMenuOpen}
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
        >
          <span className="hamburger-bar" />
          <span className="hamburger-bar" />
          <span className="hamburger-bar" />
        </button>
      </div>

      {/* Mobile Drawer Menu */}
      <div className={`mobile-nav-drawer ${mobileMenuOpen ? "open" : ""}`} aria-hidden={!mobileMenuOpen}>
        <ul className="mobile-nav-list">
          {navItems.map((item) => (
            <li key={item.id}>
              <a
                href={item.href}
                className={activeSection === item.id ? "active" : ""}
                onClick={(e) => handleLinkClick(item.id, item.href, e)}
              >
                {item.label}
              </a>
            </li>
          ))}
          <li style={{ marginTop: "8px" }}>
            <a
              href="#donate"
              className="btn-nav-donate"
              style={{ display: "inline-block", textAlign: "center", width: "100%" }}
              onClick={(e) => handleLinkClick("donate", "#donate", e)}
            >
              Donate Online 💝
            </a>
          </li>
        </ul>
      </div>
    </header>
  );
}

/* ==========================================================================
   Hero Component - Grace Fellowship Church
   Hero banner with sunset cross background, Scripture verse, and CTA buttons
   ========================================================================== */

function Hero() {
  const handleScrollTo = (sectionId, e) => {
    e.preventDefault();
    const elem = document.getElementById(sectionId);
    if (elem) {
      elem.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <section
      id="home"
      className="hero-section"
      style={{
        backgroundImage: "url('home/assets/hero_cross_sunset.jpg')"
      }}
    >
      <div className="hero-overlay" />
      <div className="home-container" style={{ width: "100%" }}>
        <div className="hero-content">
          <p className="hero-welcome">Welcome to</p>
          <h1 className="hero-title">Grace Fellowship Church</h1>
          <p className="hero-subtitle">
            A family of believers growing together in Christ's love.
          </p>
          <p className="hero-verse">
            “For where two or three gather in my name, there am I with them.” — Matthew 18:20
          </p>

          <div className="hero-actions">
            <a
              href="#service-timings"
              className="btn-hero-primary"
              onClick={(e) => handleScrollTo("service-timings", e)}
            >
              Join Us This Sunday
            </a>
            <a
              href="#sermons"
              className="btn-hero-secondary"
              onClick={(e) => handleScrollTo("sermons", e)}
            >
              <span>▶</span>
              <span>Watch Sermons</span>
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}

/* ==========================================================================
