/* ==========================================================================
   PrayerCategory Component
   Prayer Category selection dropdown with purple heart icon,
   alongside the "Submit Anonymously" toggle switch and subtitle.
   ========================================================================== */

function PrayerCategory({
  category = "",
  onChangeCategory,
  isAnonymous = false,
  onToggleAnonymous,
  error = ""
}) {
  const categories = [
    { value: "", label: "Select a category", disabled: true },
    { value: "Healing & Health", label: "Healing & Physical Health" },
    { value: "Family & Marriage", label: "Family, Marriage & Children" },
    { value: "Spiritual Growth", label: "Spiritual Growth & Deliverance" },
    { value: "Guidance & Direction", label: "Guidance, Wisdom & Major Decisions" },
    { value: "Financial & Employment", label: "Financial Provision & Employment" },
    { value: "Comfort & Grief", label: "Comfort, Grief & Loss of Loved One" },
    { value: "Salvation & Faith", label: "Salvation of Family & Loved Ones" },
    { value: "Mental & Emotional Peace", label: "Mental Health, Peace & Anxiety" },
    { value: "Thanksgiving & Praise", label: "Thanksgiving & Answered Prayer" },
    { value: "Other Need", label: "Other Personal Need" }
  ];

  return (
    <div className="prayer-category-anonymous-row">
      {/* Category Dropdown Column */}
      <div className={`prayer-form-group category-group ${error ? "has-error" : ""}`}>
        <label htmlFor="prayer-category-select" className="prayer-field-label">
          Prayer Category <span className="required-star">*</span>
        </label>

        <div className="custom-input-wrap select-wrap">
          {/* Purple Heart Icon */}
          <span className="field-icon-box heart-icon" aria-hidden="true">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
            </svg>
          </span>

          <select
            id="prayer-category-select"
            className="prayer-select-input"
            value={category}
            onChange={(e) => onChangeCategory(e.target.value)}
            aria-required="true"
            aria-invalid={!!error}
          >
            {categories.map((c, i) => (
              <option key={i} value={c.value} disabled={c.disabled}>
                {c.label}
              </option>
            ))}
          </select>

          <span className="select-dropdown-chevron" aria-hidden="true">▼</span>
        </div>

        {error && <p className="field-error-message" role="alert">{error}</p>}
      </div>

      {/* Submit Anonymously Toggle Column */}
      <div className="prayer-anonymous-toggle-wrap">
        <div className="anonymous-toggle-header">
          <label className="toggle-switch-control" htmlFor="anonymous-toggle">
            <input
              type="checkbox"
              id="anonymous-toggle"
              checked={isAnonymous}
              onChange={(e) => onToggleAnonymous(e.target.checked)}
              aria-label="Submit prayer request anonymously"
            />
            <span className="toggle-slider-round" />
          </label>
          <span className="anonymous-toggle-label">Submit Anonymously</span>
        </div>
        <p className="anonymous-toggle-subtitle">
          Your name will not be shown to the prayer team.
        </p>
      </div>
    </div>
  );
}

window.PrayerCategory = PrayerCategory;

/* ==========================================================================
   AudioRecorder Component
   Interactive voice prayer recorder:
   - Requests microphone access via getUserMedia
   - Handles permission denial gracefully with error feedback
   - Live timer (MM:SS) and pulsating audio waveform bars
   - Pause / Resume / Stop / Playback preview / Attach to request
   ========================================================================== */

function AudioRecorder({ isOpen, onClose, onAttachAudio }) {
  const [recordState, setRecordState] = React.useState("idle"); // "idle" | "recording" | "paused" | "stopped"
  const [duration, setDuration] = React.useState(0);
  const [audioUrl, setAudioUrl] = React.useState(null);
  const [audioBlob, setAudioBlob] = React.useState(null);
  const [audioFile, setAudioFile] = React.useState(null);
  const [errorMessage, setErrorMessage] = React.useState("");
  const [isPlayingPreview, setIsPlayingPreview] = React.useState(false);

  const mediaRecorderRef = React.useRef(null);
  const audioChunksRef = React.useRef([]);
  const timerIntervalRef = React.useRef(null);
  const audioPlayerRef = React.useRef(null);
  const streamRef = React.useRef(null);

  // Format seconds into MM:SS
  const formatTime = (secs) => {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  // Format file size
  const formatBytes = (bytes) => {
    if (!bytes || bytes === 0) return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
  };

  // Start recording
  const startRecording = async () => {
    setErrorMessage("");
    audioChunksRef.current = [];
    setDuration(0);

    try {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error("Audio recording is not supported in this browser.");
      }

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const mimeType = MediaRecorder.isTypeSupported("audio/webm;codecs=opus")
        ? "audio/webm;codecs=opus"
        : MediaRecorder.isTypeSupported("audio/mp4")
        ? "audio/mp4"
        : "";

      const options = mimeType ? { mimeType } : undefined;
      const mediaRecorder = new MediaRecorder(stream, options);
      mediaRecorderRef.current = mediaRecorder;

      mediaRecorder.ondataavailable = (event) => {
        if (event.data && event.data.size > 0) {
          audioChunksRef.current.push(event.data);
        }
      };

      mediaRecorder.onstop = () => {
        const mime = mimeType || "audio/webm";
        const blob = new Blob(audioChunksRef.current, { type: mime });
        const url = URL.createObjectURL(blob);
        const ext = mime.includes("mp4") ? "m4a" : "webm";
        const filename = `prayer_voice_${Date.now()}.${ext}`;
        const file = new File([blob], filename, { type: mime, lastModified: Date.now() });

        setAudioBlob(blob);
        setAudioUrl(url);
        setAudioFile(file);
        setRecordState("stopped");

        // Stop all stream tracks to turn off mic indicator
        if (streamRef.current) {
          streamRef.current.getTracks().forEach((track) => track.stop());
          streamRef.current = null;
        }
      };

      mediaRecorder.start(250);
      setRecordState("recording");

      // Start duration counter
      timerIntervalRef.current = setInterval(() => {
        setDuration((prev) => prev + 1);
      }, 1000);
    } catch (err) {
      console.error("Microphone access error:", err);
      let msg = "Microphone access was denied or unavailable. Please check your browser settings or use 'Upload Audio' instead.";
      if (err.name === "NotAllowedError" || err.name === "PermissionDeniedError") {
        msg = "Microphone permission was denied. Please allow microphone access in your browser address bar to record prayer audio.";
      } else if (err.name === "NotFoundError" || err.name === "DevicesNotFoundError") {
        msg = "No microphone hardware found on your device. You can still upload a recorded audio file.";
      }
      setErrorMessage(msg);
      setRecordState("idle");
    }
  };

  // Pause or Resume
  const togglePause = () => {
    if (!mediaRecorderRef.current) return;
    if (recordState === "recording") {
      mediaRecorderRef.current.pause();
      clearInterval(timerIntervalRef.current);
      setRecordState("paused");
    } else if (recordState === "paused") {
      mediaRecorderRef.current.resume();
      timerIntervalRef.current = setInterval(() => {
        setDuration((prev) => prev + 1);
      }, 1000);
      setRecordState("recording");
    }
  };

  // Stop recording
  const stopRecording = () => {
    if (mediaRecorderRef.current && recordState !== "idle" && recordState !== "stopped") {
      mediaRecorderRef.current.stop();
      clearInterval(timerIntervalRef.current);
    }
  };

  // Attach recorded audio to prayer form
  const handleAttach = () => {
    if (audioFile && onAttachAudio) {
      onAttachAudio({
        id: `rec-${Date.now()}`,
        file: audioFile,
        name: audioFile.name,
        size: audioFile.size,
        formattedSize: formatBytes(audioFile.size),
        duration: formatTime(duration),
        durationSeconds: duration,
        type: "audio",
        url: audioUrl,
        isRecorded: true
      });
      handleClose();
    }
  };

  // Preview Playback Toggle
  const togglePreviewPlayback = () => {
    if (!audioPlayerRef.current) return;
    if (isPlayingPreview) {
      audioPlayerRef.current.pause();
      setIsPlayingPreview(false);
    } else {
      audioPlayerRef.current.play();
      setIsPlayingPreview(true);
    }
  };

  // Cleanup on close
  const handleClose = () => {
    if (mediaRecorderRef.current && recordState === "recording") {
      mediaRecorderRef.current.stop();
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
    if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current);
    }
    if (audioPlayerRef.current) {
      audioPlayerRef.current.pause();
    }
    setRecordState("idle");
    setDuration(0);
    setAudioUrl(null);
    setAudioBlob(null);
    setAudioFile(null);
    setErrorMessage("");
    setIsPlayingPreview(false);
    if (onClose) onClose();
  };

  React.useEffect(() => {
    return () => {
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
      if (streamRef.current) {
        streamRef.current.getTracks().forEach((t) => t.stop());
      }
    };
  }, []);

  if (!isOpen) return null;

  return (
    <div className="audio-recorder-modal-overlay" role="dialog" aria-modal="true" aria-labelledby="recorder-title">
      <div className="audio-recorder-modal-card">
        {/* Modal Header */}
        <div className="recorder-modal-header">
          <div className="recorder-header-left">
            <span className="recorder-mic-badge">🎙️</span>
            <div>
              <h3 id="recorder-title" className="recorder-title">Record Voice Prayer</h3>
              <p className="recorder-subtitle">Speak your prayer request directly from your heart</p>
            </div>
          </div>
          <button type="button" className="btn-modal-close" onClick={handleClose} aria-label="Close recorder">
            ✕
          </button>
        </div>

        {/* Error Callout */}
        {errorMessage && (
          <div className="recorder-error-alert" role="alert">
            <span className="alert-icon">⚠️</span>
            <span>{errorMessage}</span>
          </div>
        )}

        {/* Recording Visual Area */}
        <div className="recorder-visual-stage">
          {/* Animated Waveform Bars */}
          <div className={`audio-waveform-container ${recordState === "recording" ? "is-live" : ""}`}>
            {[40, 65, 85, 45, 95, 60, 75, 100, 70, 50, 85, 40, 60, 90, 55].map((h, i) => (
              <span
                key={i}
                className="waveform-bar"
                style={{
                  "--bar-height": `${recordState === "recording" ? h : 20}%`,
                  "--bar-delay": `${(i * 0.08).toFixed(2)}s`
                }}
              />
            ))}
          </div>

          {/* Time Counter */}
          <div className="recorder-time-display">
            {recordState === "recording" && <span className="recording-live-dot" />}
            <span className="recorder-time-digits">{formatTime(duration)}</span>
            <span className="recorder-state-label">
              {recordState === "idle" && "Ready to record"}
              {recordState === "recording" && "Recording..."}
              {recordState === "paused" && "Paused"}
              {recordState === "stopped" && "Recording finished"}
            </span>
          </div>

          {/* Hidden HTML5 Audio Element for preview */}
          {audioUrl && (
            <audio
              ref={audioPlayerRef}
              src={audioUrl}
              onEnded={() => setIsPlayingPreview(false)}
              style={{ display: "none" }}
            />
          )}
        </div>

        {/* Action Controls Footer */}
        <div className="recorder-controls-footer">
          {recordState === "idle" && (
            <button
              type="button"
              className="btn-recorder-action btn-start-record"
              onClick={startRecording}
            >
              <span className="btn-record-circle" />
              <span>Start Recording</span>
            </button>
          )}

          {(recordState === "recording" || recordState === "paused") && (
            <div className="recorder-active-actions">
              <button
                type="button"
                className="btn-recorder-action btn-pause-record"
                onClick={togglePause}
              >
                {recordState === "recording" ? "⏸ Pause" : "▶ Resume"}
              </button>

              <button
                type="button"
                className="btn-recorder-action btn-stop-record"
                onClick={stopRecording}
              >
                ⏹ Stop Recording
              </button>
            </div>
          )}

          {recordState === "stopped" && (
            <div className="recorder-finished-actions">
              <button
                type="button"
                className="btn-recorder-action btn-preview-playback"
                onClick={togglePreviewPlayback}
              >
                {isPlayingPreview ? "⏸ Pause Preview" : "▶ Play Preview"}
              </button>

              <button
                type="button"
                className="btn-recorder-action btn-rerecord"
                onClick={startRecording}
              >
                🔄 Re-record
              </button>

              <button
                type="button"
                className="btn-recorder-action btn-attach-audio"
                onClick={handleAttach}
              >
                ✓ Attach Audio ({formatBytes(audioBlob?.size || 0)})
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

window.AudioRecorder = AudioRecorder;

/* ==========================================================================
   MediaUploader Component
   The 5 Media Action Cards matching the screenshot:
   1. Record Audio
   2. Upload Audio
   3. Upload Video
   4. Upload Photos
   5. Upload Document
   Handles multi-file selection, format validation, and 100 MB size limit.
   ========================================================================== */

function MediaUploader({
  onAddFiles,
  onOpenRecorder,
  currentTotalSize = 0,
  maxTotalSize = 100 * 1024 * 1024 // 100 MB
}) {
  const audioInputRef = React.useRef(null);
  const videoInputRef = React.useRef(null);
  const imageInputRef = React.useRef(null);
  const docInputRef = React.useRef(null);

  const [validationError, setValidationError] = React.useState("");

  const formatBytes = (bytes) => {
    if (!bytes || bytes === 0) return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
  };

  const handleFilesSelected = (event, expectedType) => {
    setValidationError("");
    const fileList = event.target.files;
    if (!fileList || fileList.length === 0) return;

    const filesArray = Array.from(fileList);
    let newTotal = currentTotalSize;
    const validProcessedFiles = [];
    const errors = [];

    // Allowed extensions & mime categories
    const allowedExtensions = {
      audio: [".mp3", ".m4a", ".wav", ".aac", ".ogg", ".flac", ".wma"],
      video: [".mp4", ".mov", ".avi", ".webm", ".mkv", ".wmv", ".m4v"],
      image: [".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp"],
      document: [".pdf", ".docx", ".doc", ".txt", ".rtf"]
    };

    for (const file of filesArray) {
      const ext = "." + (file.name.split(".").pop() || "").toLowerCase();
      let matchedType = expectedType;

      // Validate extension
      const isValidExt = allowedExtensions[expectedType] && allowedExtensions[expectedType].includes(ext);
      if (!isValidExt) {
        errors.push(`"${file.name}" is not a supported ${expectedType} format.`);
        continue;
      }

      // Check cumulative size
      if (newTotal + file.size > maxTotalSize) {
        const remaining = Math.max(0, maxTotalSize - newTotal);
        errors.push(`Cannot add "${file.name}" (${formatBytes(file.size)}). Exceeds 100 MB total limit. Space remaining: ${formatBytes(remaining)}.`);
        continue;
      }

      newTotal += file.size;

      // Generate preview URL
      const url = URL.createObjectURL(file);

      validProcessedFiles.push({
        id: `att-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        file: file,
        name: file.name,
        size: file.size,
        formattedSize: formatBytes(file.size),
        type: expectedType,
        url: url,
        duration: expectedType === "audio" ? "01:36" : undefined
      });
    }

    if (errors.length > 0) {
      setValidationError(errors.join(" "));
    }

    if (validProcessedFiles.length > 0 && onAddFiles) {
      onAddFiles(validProcessedFiles);
    }

    // Reset input so same file can be re-selected if removed
    event.target.value = "";
  };

  return (
    <div className="prayer-media-uploader-section">
      {/* Header Row */}
      <div className="media-uploader-header-row">
        <label className="prayer-field-label media-label">
          Add Media <span className="label-optional">(Optional)</span>
        </label>
        <span className="media-limit-hint">
          You can add multiple files (Max total: 100 MB)
        </span>
      </div>

      {/* Validation Error Banner */}
      {validationError && (
        <div className="media-validation-alert" role="alert">
          <span className="alert-icon">⚠️</span>
          <span>{validationError}</span>
          <button type="button" className="btn-dismiss-alert" onClick={() => setValidationError("")}>✕</button>
        </div>
      )}

      {/* Hidden File Inputs */}
      <input
        ref={audioInputRef}
        type="file"
        multiple
        accept="audio/*, .mp3, .m4a, .wav, .aac, .ogg, .flac"
        style={{ display: "none" }}
        onChange={(e) => handleFilesSelected(e, "audio")}
      />
      <input
        ref={videoInputRef}
        type="file"
        multiple
        accept="video/*, .mp4, .mov, .avi, .webm, .mkv"
        style={{ display: "none" }}
        onChange={(e) => handleFilesSelected(e, "video")}
      />
      <input
        ref={imageInputRef}
        type="file"
        multiple
        accept="image/*, .jpg, .jpeg, .png, .webp, .gif"
        style={{ display: "none" }}
        onChange={(e) => handleFilesSelected(e, "image")}
      />
      <input
        ref={docInputRef}
        type="file"
        multiple
        accept=".pdf, .docx, .doc, .txt"
        style={{ display: "none" }}
        onChange={(e) => handleFilesSelected(e, "document")}
      />

      {/* 5 Action Cards Grid Matching Screenshot */}
      <div className="media-action-buttons-grid">
        {/* 1. Record Audio */}
        <button
          type="button"
          className="btn-media-pill btn-record-audio-pill active-blue"
          onClick={onOpenRecorder}
          title="Record your voice prayer request"
        >
          <div className="media-pill-icon-box mic-icon-box">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" />
              <path d="M19 10v2a7 7 0 0 1-14 0v-2" />
              <line x1="12" y1="19" x2="12" y2="23" />
              <line x1="8" y1="23" x2="16" y2="23" />
            </svg>
          </div>
          <span className="media-pill-label">Record Audio</span>
        </button>

        {/* 2. Upload Audio */}
        <button
          type="button"
          className="btn-media-pill"
          onClick={() => audioInputRef.current && audioInputRef.current.click()}
          title="Upload audio files (mp3, m4a, wav)"
        >
          <div className="media-pill-icon-box">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M3 18v-6a9 9 0 0 1 18 0v6" />
              <path d="M21 19a2 2 0 0 1-2 2h-1a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2h3zM3 19a2 2 0 0 0 2 2h1a2 2 0 0 0 2-2v-3a2 2 0 0 0-2-2H3z" />
            </svg>
          </div>
          <span className="media-pill-label">Upload Audio</span>
        </button>

        {/* 3. Upload Video */}
        <button
          type="button"
          className="btn-media-pill"
          onClick={() => videoInputRef.current && videoInputRef.current.click()}
          title="Upload video files (mp4, mov, webm)"
        >
          <div className="media-pill-icon-box purple-icon-box">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <rect x="2" y="4" width="20" height="16" rx="2.18" ry="2.18" />
              <polygon points="10 8 16 12 10 16 10 8" fill="currentColor" />
            </svg>
          </div>
          <span className="media-pill-label">Upload Video</span>
        </button>

        {/* 4. Upload Photos */}
        <button
          type="button"
          className="btn-media-pill"
          onClick={() => imageInputRef.current && imageInputRef.current.click()}
          title="Upload photos (jpg, png, webp)"
        >
          <div className="media-pill-icon-box magenta-icon-box">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <rect x="3" y="3" width="18" height="18" rx="2" ry="2" />
              <circle cx="8.5" cy="8.5" r="1.5" />
              <polyline points="21 15 16 10 5 21" />
            </svg>
          </div>
          <span className="media-pill-label">Upload Photos</span>
        </button>

        {/* 5. Upload Document */}
        <button
          type="button"
          className="btn-media-pill"
          onClick={() => docInputRef.current && docInputRef.current.click()}
          title="Upload documents (pdf, docx, txt)"
        >
          <div className="media-pill-icon-box blue-doc-icon-box">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
              <polyline points="14 2 14 8 20 8" />
              <line x1="16" y1="13" x2="8" y2="13" />
              <line x1="16" y1="17" x2="8" y2="17" />
              <polyline points="10 9 9 9 8 9" />
            </svg>
          </div>
          <span className="media-pill-label">Upload Document</span>
        </button>
      </div>
    </div>
  );
}

window.MediaUploader = MediaUploader;

/* ==========================================================================
   AttachmentPreview Component
   Displays uploaded and recorded media attachments matching the screenshot:
   - Audio item: purple badge, file name, size/duration, waveform bars, play button, remove X
   - Photo item: thumbnail preview, file name, size, eye view button, remove X
   - Document item: red PDF badge, file name, size, eye view button, remove X
   - Video item: purple video badge, file name, size, play preview button, remove X
   ========================================================================== */

function AttachmentPreview({
  attachments = [],
  onRemoveAttachment,
  onPreviewItem
}) {
  const [playingAudioId, setPlayingAudioId] = React.useState(null);
  const audioElementsRef = React.useRef({});

  const toggleAudioPlay = (id, url) => {
    // If clicking already playing audio
    if (playingAudioId === id) {
      if (audioElementsRef.current[id]) {
        audioElementsRef.current[id].pause();
      }
      setPlayingAudioId(null);
      return;
    }

    // Stop previous audio
    if (playingAudioId && audioElementsRef.current[playingAudioId]) {
      audioElementsRef.current[playingAudioId].pause();
    }

    if (!audioElementsRef.current[id]) {
      const audio = new Audio(url);
      audio.onended = () => setPlayingAudioId(null);
      audioElementsRef.current[id] = audio;
    }

    audioElementsRef.current[id].play().then(() => {
      setPlayingAudioId(id);
    }).catch((err) => {
      console.warn("Audio play prevented:", err);
      setPlayingAudioId(null);
    });
  };

  const handleRemove = (id) => {
    if (playingAudioId === id && audioElementsRef.current[id]) {
      audioElementsRef.current[id].pause();
      setPlayingAudioId(null);
    }
    if (audioElementsRef.current[id]) {
      delete audioElementsRef.current[id];
    }
    if (onRemoveAttachment) {
      onRemoveAttachment(id);
    }
  };

  if (!attachments || attachments.length === 0) return null;

  return (
    <div className="prayer-attachments-list-container" aria-label="Attached Media Files">
      {attachments.map((item) => {
        const isAudio = item.type === "audio";
        const isImage = item.type === "image";
        const isDoc = item.type === "document";
        const isVideo = item.type === "video";
        const isPlayingThisAudio = playingAudioId === item.id;

        return (
          <div key={item.id} className={`attachment-card-row type-${item.type}`}>
            {/* Left Icon / Thumbnail */}
            <div className="attachment-leading-col">
              {isAudio && (
                <div className="attachment-icon-box audio-purple-box" aria-hidden="true">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                    <polygon points="5 3 19 12 5 21 5 3" fill="currentColor" opacity="0.9" />
                  </svg>
                </div>
              )}

              {isImage && (
                <div className="attachment-thumb-wrap">
                  {item.url ? (
                    <img src={item.url} alt={item.name} className="attachment-img-thumbnail" />
                  ) : (
                    <div className="attachment-icon-box image-orange-box">🖼️</div>
                  )}
                </div>
              )}

              {isDoc && (
                <div className="attachment-icon-box doc-red-box" aria-hidden="true">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                    <polyline points="14 2 14 8 20 8" />
                    <path d="M9 13h6" />
                    <path d="M9 17h4" />
                  </svg>
                </div>
              )}

              {isVideo && (
                <div className="attachment-icon-box video-purple-box" aria-hidden="true">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="2" y="4" width="20" height="16" rx="2.18" ry="2.18" />
                    <polygon points="10 8 16 12 10 16 10 8" fill="currentColor" />
                  </svg>
                </div>
              )}
            </div>

            {/* Info Column (Name & Size/Duration) */}
            <div className="attachment-info-col">
              <span className="attachment-file-name" title={item.name}>
                {item.name}
              </span>
              <span className="attachment-file-meta">
                {item.formattedSize}
                {item.duration && ` • ${item.duration}`}
              </span>
            </div>

            {/* Center Waveform Graphic for Audio */}
            {isAudio && (
              <div className="attachment-waveform-col" aria-hidden="true">
                <div className={`preview-waveform-bars ${isPlayingThisAudio ? "playing-bars" : ""}`}>
                  {[4, 8, 14, 20, 12, 16, 24, 18, 10, 16, 22, 14, 8, 12, 18, 22, 16, 12, 6, 10, 18, 14, 8].map((h, i) => (
                    <span 
                      key={i} 
                      className="wave-tick" 
                      style={{ 
                        height: `${h}px`,
                        animationDelay: `${(i * 0.05).toFixed(2)}s`
                      }} 
                    />
                  ))}
                </div>
              </div>
            )}

            {/* Spacer for non-audio */}
            {!isAudio && <div className="attachment-spacer-col" />}

            {/* Action Buttons: Preview & Remove */}
            <div className="attachment-actions-col">
              {/* Audio Play/Pause Button */}
              {isAudio && (
                <button
                  type="button"
                  className={`btn-attachment-action btn-play-audio ${isPlayingThisAudio ? "is-playing" : ""}`}
                  onClick={() => toggleAudioPlay(item.id, item.url)}
                  title={isPlayingThisAudio ? "Pause Audio" : "Play Audio"}
                  aria-label={isPlayingThisAudio ? "Pause Audio" : "Play Audio"}
                >
                  {isPlayingThisAudio ? (
                    <span className="play-icon-symbol">⏸</span>
                  ) : (
                    <span className="play-icon-symbol">▶</span>
                  )}
                </button>
              )}

              {/* View Eye Button for Images, Documents, Videos */}
              {(isImage || isDoc || isVideo) && (
                <button
                  type="button"
                  className="btn-attachment-action btn-view-file"
                  onClick={() => onPreviewItem && onPreviewItem(item)}
                  title="View attachment preview"
                  aria-label={`View ${item.name}`}
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                    <circle cx="12" cy="12" r="3" />
                  </svg>
                </button>
              )}

              {/* Remove "X" Button */}
              <button
                type="button"
                className="btn-attachment-action btn-remove-file"
                onClick={() => handleRemove(item.id)}
                title="Remove attachment"
                aria-label={`Remove ${item.name}`}
              >
                ✕
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

window.AttachmentPreview = AttachmentPreview;

/* ==========================================================================
   PrayerForm Component
   The central "Send a Prayer Request" card matching the uploaded screenshot:
   - Name, Email, Phone inputs with embedded icons
   - Prayer Category dropdown & Submit Anonymously toggle
   - Prayer request textarea with 1,000 character counter
   - Add Media (Record Audio, Upload Audio, Video, Photos, Document)
   - Attachment previews with waveform audio player and remove controls
   - Send Prayer Request action button
   - Privacy Callout banner
   - Submission confirmation modal with reference number
   ========================================================================== */

function PrayerForm() {
  // Form State
  const [name, setName] = React.useState("");
  const [email, setEmail] = React.useState("");
  const [phone, setPhone] = React.useState("");
  const [category, setCategory] = React.useState("");
  const [isAnonymous, setIsAnonymous] = React.useState(false);
  const [requestText, setRequestText] = React.useState("");
  const [attachments, setAttachments] = React.useState([]);

  // UI / Modal State
  const [isRecordingOpen, setIsRecordingOpen] = React.useState(false);
  const [isSubmitting, setIsSubmitting] = React.useState(false);
  const [errors, setErrors] = React.useState({});
  const [submissionResult, setSubmissionResult] = React.useState(null);
  const [previewingItem, setPreviewingItem] = React.useState(null); // For lightbox

  // Max character limit
  const MAX_CHAR_LIMIT = 1000;
  const MAX_TOTAL_SIZE = 100 * 1024 * 1024; // 100 MB

  // Calculate current total attachment size
  const totalAttachmentSize = React.useMemo(() => {
    return attachments.reduce((acc, curr) => acc + (curr.size || 0), 0);
  }, [attachments]);

  // Handle adding new attachments
  const handleAddAttachments = (newFiles) => {
    setAttachments((prev) => [...prev, ...newFiles]);
    // Clear attachment error if any
    setErrors((prev) => ({ ...prev, attachments: "", general: "" }));
  };

  // Handle removing attachment
  const handleRemoveAttachment = (idToRemove) => {
    setAttachments((prev) => prev.filter((item) => item.id !== idToRemove));
  };

  // Add recorded audio
  const handleAttachRecordedAudio = (audioItem) => {
    setAttachments((prev) => [...prev, audioItem]);
  };

  // Validate form before submission
  const validateForm = () => {
    const newErrors = {};

    if (!category.trim()) {
      newErrors.category = "Please select a prayer category.";
    }

    const hasText = requestText.trim().length > 0;
    const hasAttachments = attachments.length > 0;

    if (!hasText && !hasAttachments) {
      newErrors.requestText = "Please write your prayer request or attach an audio/video message.";
    } else if (hasText && requestText.length > MAX_CHAR_LIMIT) {
      newErrors.requestText = `Prayer request cannot exceed ${MAX_CHAR_LIMIT} characters (Currently: ${requestText.length}).`;
    }

    if (email.trim()) {
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailPattern.test(email.trim())) {
        newErrors.email = "Please enter a valid email address.";
      }
    }

    if (totalAttachmentSize > MAX_TOTAL_SIZE) {
      newErrors.attachments = "Total attachment size cannot exceed 100 MB. Please remove some files.";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Submit Prayer Request
  const handleSubmit = async (e) => {
    if (e) e.preventDefault();

    if (!validateForm()) {
      // Scroll to first error
      const firstErrorEl = document.querySelector(".field-error-message, .form-general-error");
      if (firstErrorEl) {
        firstErrorEl.scrollIntoView({ behavior: "smooth", block: "center" });
      }
      return;
    }

    setIsSubmitting(true);
    setErrors({});

    const requesterName = isAnonymous ? "Anonymous" : (name.trim() || "Friend in Christ");
    const contactInfo = isAnonymous 
      ? "Anonymous" 
      : [email.trim(), phone.trim()].filter(Boolean).join(" | ") || "Not provided";

    let detailedMessage = `[Category: ${category}] ${requestText.trim()}`;
    if (attachments.length > 0) {
      detailedMessage += `\n[Attachments (${attachments.length})]: ${attachments.map((a) => `${a.name} (${a.formattedSize})`).join(", ")}`;
    }

    const payload = {
      name: requesterName,
      contact: contactInfo,
      request: detailedMessage
    };

    try {
      const apiBase = (window.location.origin && window.location.origin.includes(":8000")) ? "" : "http://localhost:8000";
      const response = await fetch(`${apiBase}/api/prayer-request`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(payload)
      });

      if (response.ok) {
        const data = await response.json();
        setSubmissionResult({
          requestId: data.request_id || `PR-${Date.now().toString().slice(-6)}`,
          message: data.message || "Thank you! Your prayer request has been received by our pastoral prayer team.",
          timestamp: data.timestamp || new Date().toISOString(),
          category: category,
          isAnonymous: isAnonymous,
          attachmentsCount: attachments.length
        });
        setIsSubmitting(false);
        return;
      }
    } catch (err) {
      console.warn("Backend API not reachable. Creating safe offline confirmation.", err);
    }

    // Clean client fallback if backend is offline
    const clientRefId = `PR-${new Date().getFullYear()}-${Math.floor(100000 + Math.random() * 900000)}`;
    setSubmissionResult({
      requestId: clientRefId,
      message: `Thank you${isAnonymous ? "" : `, ${name.trim() || "Friend"}`}! Your prayer request has been submitted. Our pastoral prayer warriors will hold you in prayer.`,
      timestamp: new Date().toISOString(),
      category: category,
      isAnonymous: isAnonymous,
      attachmentsCount: attachments.length
    });
    setIsSubmitting(false);
  };

  // Reset form to submit another request
  const handleResetForm = () => {
    setName("");
    setEmail("");
    setPhone("");
    setCategory("");
    setIsAnonymous(false);
    setRequestText("");
    setAttachments([]);
    setErrors({});
    setSubmissionResult(null);
  };

  return (
    <div className="prayer-form-card-container">
      {/* SUCCESS CONFIRMATION MODAL */}
      {submissionResult && (
        <div className="prayer-success-modal-overlay" role="dialog" aria-modal="true" aria-labelledby="success-modal-title">
          <div className="prayer-success-card">
            <div className="success-icon-badge">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
                <polyline points="22 4 12 14.01 9 11.01" />
              </svg>
            </div>

            <h2 id="success-modal-title" className="success-title">Prayer Request Received</h2>
            <p className="success-message">{submissionResult.message}</p>

            <div className="success-reference-box">
              <span className="ref-label">Reference Number</span>
              <span className="ref-number">{submissionResult.requestId}</span>
              <span className="ref-hint">Please save this reference number for pastoral follow-up.</span>
            </div>

            <div className="success-meta-details">
              <div className="meta-detail-row">
                <span className="detail-key">Category:</span>
                <span className="detail-val">{submissionResult.category}</span>
              </div>
              <div className="meta-detail-row">
                <span className="detail-key">Privacy Mode:</span>
                <span className="detail-val">{submissionResult.isAnonymous ? "Anonymous Submission" : "Standard Contact"}</span>
              </div>
              {submissionResult.attachmentsCount > 0 && (
                <div className="meta-detail-row">
                  <span className="detail-key">Attachments:</span>
                  <span className="detail-val">{submissionResult.attachmentsCount} file(s) attached</span>
                </div>
              )}
            </div>

            <div className="success-quote-box">
              <p>&ldquo;And this is the confidence that we have toward him, that if we ask anything according to his will he hears us.&rdquo;</p>
              <span>&mdash; 1 John 5:14</span>
            </div>

            <button
              type="button"
              className="btn-submit-another"
              onClick={handleResetForm}
            >
              Submit Another Prayer Request
            </button>
          </div>
        </div>
      )}

      {/* LIGHTBOX PREVIEW MODAL */}
      {previewingItem && (
        <div className="lightbox-modal-overlay" onClick={() => setPreviewingItem(null)}>
          <div className="lightbox-content-card" onClick={(e) => e.stopPropagation()}>
            <div className="lightbox-header">
              <span className="lightbox-filename">{previewingItem.name}</span>
              <button type="button" className="btn-lightbox-close" onClick={() => setPreviewingItem(null)}>✕</button>
            </div>
            <div className="lightbox-body">
              {previewingItem.type === "image" && (
                <img src={previewingItem.url} alt={previewingItem.name} className="lightbox-full-img" />
              )}
              {previewingItem.type === "video" && (
                <video src={previewingItem.url} controls autoPlay className="lightbox-full-video" />
              )}
              {previewingItem.type === "document" && (
                <div className="lightbox-doc-preview">
                  <span className="doc-big-icon">📄</span>
                  <p>{previewingItem.name} ({previewingItem.formattedSize})</p>
                  <a href={previewingItem.url} download={previewingItem.name} className="btn-doc-download">
                    ⬇ Download File
                  </a>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* AUDIO RECORDER MODAL */}
      <window.AudioRecorder
        isOpen={isRecordingOpen}
        onClose={() => setIsRecordingOpen(false)}
        onAttachAudio={handleAttachRecordedAudio}
      />

      {/* MAIN CARD */}
      <article className="prayer-request-main-card" aria-label="Send a Prayer Request Form">
        {/* Card Header matching screenshot */}
        <header className="card-top-header">
          <div className="card-header-icon-box">
            {/* Blue square pen/edit writing icon */}
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
              <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
            </svg>
          </div>
          <div className="card-header-titles">
            <h2 className="card-primary-title">Send a Prayer Request</h2>
            <p className="card-secondary-subtitle">Let us know how we can pray for you.</p>
          </div>
        </header>

        {/* Form Body */}
        <form className="prayer-actual-form" onSubmit={handleSubmit} noValidate>
          {/* Row 1: Name and Email */}
          <div className="form-fields-grid-two-col">
            {/* Name Field */}
            <div className={`prayer-form-group ${isAnonymous ? "is-disabled" : ""}`}>
              <label htmlFor="requester-name" className="prayer-field-label">
                Your Name <span className="label-optional">(Optional)</span>
              </label>
              <div className="custom-input-wrap">
                <span className="field-icon-box" aria-hidden="true">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
                    <circle cx="12" cy="7" r="4" />
                  </svg>
                </span>
                <input
                  type="text"
                  id="requester-name"
                  className="prayer-text-input"
                  placeholder={isAnonymous ? "Anonymous — Name hidden" : "Enter your name"}
                  value={isAnonymous ? "" : name}
                  onChange={(e) => setName(e.target.value)}
                  disabled={isAnonymous}
                  maxLength={100}
                />
              </div>
            </div>

            {/* Email Field */}
            <div className={`prayer-form-group ${errors.email ? "has-error" : ""}`}>
              <label htmlFor="requester-email" className="prayer-field-label">
                Email <span className="label-optional">(Optional)</span>
              </label>
              <div className="custom-input-wrap">
                <span className="field-icon-box" aria-hidden="true">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z" />
                    <polyline points="22,6 12,13 2,6" />
                  </svg>
                </span>
                <input
                  type="email"
                  id="requester-email"
                  className="prayer-text-input"
                  placeholder="Enter your email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  maxLength={120}
                />
              </div>
              {errors.email && <p className="field-error-message" role="alert">{errors.email}</p>}
            </div>
          </div>

          {/* Row 2: Phone */}
          <div className="prayer-form-group">
            <label htmlFor="requester-phone" className="prayer-field-label">
              Phone <span className="label-optional">(Optional)</span>
            </label>
            <div className="custom-input-wrap">
              <span className="field-icon-box" aria-hidden="true">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z" />
                </svg>
              </span>
              <input
                type="tel"
                id="requester-phone"
                className="prayer-text-input"
                placeholder="Enter your phone number"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                maxLength={30}
              />
            </div>
          </div>

          {/* Row 3: Category & Anonymous Toggle */}
          <window.PrayerCategory
            category={category}
            onChangeCategory={setCategory}
            isAnonymous={isAnonymous}
            onToggleAnonymous={setIsAnonymous}
            error={errors.category}
          />

          {/* Row 4: Prayer Request Textarea */}
          <div className={`prayer-form-group textarea-group ${errors.requestText ? "has-error" : ""}`}>
            <label htmlFor="prayer-request-text" className="prayer-field-label">
              Your Prayer Request <span className="required-star">*</span>
            </label>

            <div className="textarea-container">
              <textarea
                id="prayer-request-text"
                className="prayer-textarea"
                rows="5"
                placeholder="Type your prayer request here..."
                value={requestText}
                onChange={(e) => {
                  if (e.target.value.length <= MAX_CHAR_LIMIT) {
                    setRequestText(e.target.value);
                  }
                }}
                aria-required="true"
                aria-invalid={!!errors.requestText}
              />
            </div>

            {/* Character Count Row */}
            <div className="textarea-footer-row">
              {errors.requestText ? (
                <p className="field-error-message" role="alert">{errors.requestText}</p>
              ) : <span />}
              <span className={`char-counter-label ${requestText.length >= MAX_CHAR_LIMIT ? "at-limit" : ""}`}>
                {requestText.length} / {MAX_CHAR_LIMIT}
              </span>
            </div>
          </div>

          {/* Row 5: Add Media Uploader */}
          <window.MediaUploader
            onAddFiles={handleAddAttachments}
            onOpenRecorder={() => setIsRecordingOpen(true)}
            currentTotalSize={totalAttachmentSize}
            maxTotalSize={MAX_TOTAL_SIZE}
          />

          {/* Row 6: Attachment Previews */}
          <window.AttachmentPreview
            attachments={attachments}
            onRemoveAttachment={handleRemoveAttachment}
            onPreviewItem={setPreviewingItem}
          />

          {/* General Form Error if any */}
          {errors.general && (
            <div className="form-general-error" role="alert">
              ⚠️ {errors.general}
            </div>
          )}

          {/* Row 7: Send Prayer Request Button */}
          <div className="form-submit-row">
            <button
              type="submit"
              className="btn-send-prayer-request"
              disabled={isSubmitting}
            >
              {isSubmitting ? (
                <span className="submit-spinner-text">
                  <span className="submit-spinner" />
                  Sending Prayer Request...
                </span>
              ) : (
                <span className="submit-normal-content">
                  {/* Paper Airplane Send Icon */}
                  <svg className="send-plane-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                    <line x1="22" y1="2" x2="11" y2="13" />
                    <polygon points="22 2 15 22 11 13 2 9 22 2" fill="currentColor" />
                  </svg>
                  <span>Send Prayer Request</span>
                </span>
              )}
            </button>
          </div>

          {/* Row 8: Green Privacy Callout Banner matching screenshot */}
          <div className="prayer-privacy-callout-banner" role="note">
            <div className="privacy-shield-icon-box" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
                <polyline points="9 12 11 14 15 10" />
              </svg>
            </div>
            <p className="privacy-callout-text">
              Your request is private and will be seen only by the church prayer team.
            </p>
          </div>
        </form>
      </article>
    </div>
  );
}

window.PrayerForm = PrayerForm;

/* ==========================================================================
   PrayerRequestPage Component
   Main container for Prayer Request feature:
   - Fixed Floating Church Navigation Bar
   - PrayerHero Banner
   - Two-column responsive desktop layout (PrayerForm + PrayerGuidelines)
   - Church Footer
   ========================================================================== */

function PrayerRequestPage() {
  const [mobileMenuOpen, setMobileMenuOpen] = React.useState(false);
  const [isScrolled, setIsScrolled] = React.useState(false);

  React.useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 20) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const navLinks = [
