          {/* Desktop Nav Links */}
          <nav className="church-nav-desktop-menu" aria-label="Main Navigation">
            {navLinks.map((item, idx) => (
              <a
                key={idx}
                href={item.href}
                className={`church-nav-link ${item.active ? "is-active" : ""}`}
              >
                {item.label}
              </a>
            ))}
          </nav>

          {/* Nav Right Utilities */}
          <div className="church-nav-right-cluster">
            {/* Search Icon */}
            <a
