/* ==========================================================================
   Grace Fellowship Church - Prayer Request Design System
   Exact pixel-perfect recreation of uploaded screenshot UI reference:
   - Church Navigation Bar
   - Sunrise Cross Hero Banner
   - Floating "Send a Prayer Request" Card
   - Embedded Input Icons & Category Dropdown
   - Anonymous Toggle Switch
   - 1,000 Char Counter Textarea
   - 5 Media Action Cards (Record Audio, Upload Audio, Video, Photos, Doc)
   - Waveform Audio Attachment, Photo Thumbnail & PDF Badges
   - Blue "Send Prayer Request" Button
   - Green Privacy Callout Banner
   - Responsive Desktop 2-Column with Scripture Promises & Pastoral Guidelines
   ========================================================================== */

/* Typography Imports */
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@600;700;800&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

:root {
  /* Colors */
  --pr-navy-900: #0a1526;
  --pr-navy-800: #0f1e36;
  --pr-navy-700: #172a4c;
  --pr-navy-600: #1e3a68;

  --pr-blue-600: #0066cc;
  --pr-blue-500: #0284c7;
  --pr-blue-400: #38bdf8;
  --pr-blue-100: #e0f2fe;
  --pr-blue-50: #f0f9ff;

  --pr-gold-600: #c59b27;
  --pr-gold-500: #f59e0b;
  --pr-gold-100: #fef3c7;

  --pr-slate-900: #0f172a;
  --pr-slate-700: #334155;
  --pr-slate-600: #475569;
  --pr-slate-500: #64748b;
  --pr-slate-400: #94a3b8;
  --pr-slate-200: #e2e8f0;
  --pr-slate-100: #f1f5f9;
  --pr-slate-50: #f8fafc;

  --pr-green-800: #065f46;
  --pr-green-700: #047857;
  --pr-green-500: #10b981;
  --pr-green-100: #d1fae5;
  --pr-green-50: #ecfdf5;

  --pr-purple-600: #7c3aed;
  --pr-purple-500: #8b5cf6;
  --pr-purple-100: #ede9fe;

  --pr-red-600: #dc2626;
  --pr-red-100: #fee2e2;

  --pr-white: #ffffff;

  /* Typography */
  --font-serif-title: 'Cinzel', Georgia, serif;
  --font-serif-body: 'Lora', Georgia, serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Shadows */
  --shadow-card: 0 10px 30px -5px rgba(15, 30, 54, 0.08), 0 20px 40px -15px rgba(15, 30, 54, 0.12);
  --shadow-subtle: 0 2px 8px rgba(15, 30, 54, 0.04);
  --shadow-hover: 0 8px 24px rgba(15, 30, 54, 0.1);
  --shadow-modal: 0 25px 60px -15px rgba(15, 30, 54, 0.35);

  /* Radius */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-pill: 9999px;
}

/* Base Styles */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: #f4f7fb;
  color: var(--pr-slate-700);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

.prayer-request-page-root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ==========================================================================
   1. Church Navigation Bar
   ========================================================================== */
