  border: none;
  background: transparent;
  padding: 10px 28px 10px 0;
  font-family: inherit;
  font-size: 0.95rem;
  color: var(--pr-navy-800);
  font-weight: 500;
  outline: none;
  cursor: pointer;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
}

.select-dropdown-chevron {
  position: absolute;
  right: 14px;
  pointer-events: none;
  font-size: 0.72rem;
  color: var(--pr-slate-400);
